const char kComputeMember[] = "u_srpss_compute";

namespace {

QAtomicInteger<int> g_buffers { 0 };
QAtomicInteger<qint64> g_bufferBytes { 0 };
QAtomicInteger<int> g_images { 0 };
QAtomicInteger<qint64> g_imageBytes { 0 };
QAtomicInteger<qint64> g_dispatches { 0 };
QAtomicInteger<qint64> g_computePasses { 0 };
QAtomicInteger<qint64> g_skipped { 0 };
QAtomicInteger<qint64> g_clears { 0 };
QAtomicInteger<qint64> g_copies { 0 };
QAtomicInteger<qint64> g_imageZeroUploads { 0 };
QAtomicInteger<qint64> g_objectsCreated { 0 };
QAtomicInteger<int> g_readbacksPending { 0 };
QAtomicInteger<qint64> g_statesLost { 0 };
QAtomicInteger<int> g_writeAsRead { 0 };
QAtomicInteger<int> g_singlePass { 0 };
QAtomicInteger<int> g_triggerEveryRecord { 0 };
QAtomicInteger<int> g_skipStorageRelease { 0 };

const char *const kAccessNames[] = { "read", "write", "read_write" };
const char *const kResourceNames[] = { "buffer", "image", "stream", "mesh" };

struct FormatName
{
    const char *name;
    QRhiTexture::Format format;
    int texelBytes;
    int reflected;      // QShaderDescription::ImageFormat
};
const FormatName kFormats[] = {
    { "rgba8", QRhiTexture::RGBA8, 4, int(QShaderDescription::ImageFormatRgba8) },
    { "rgba16f", QRhiTexture::RGBA16F, 8, int(QShaderDescription::ImageFormatRgba16f) },
    { "rgba32f", QRhiTexture::RGBA32F, 16, int(QShaderDescription::ImageFormatRgba32f) },
    { "r16f", QRhiTexture::R16F, 2, int(QShaderDescription::ImageFormatR16f) },
    { "r32f", QRhiTexture::R32F, 4, int(QShaderDescription::ImageFormatR32f) },
};

bool identifier(const QByteArray &name)
{
    if (name.isEmpty() || name.size() > 64 || (name.at(0) >= '0' && name.at(0) <= '9'))
        return false;
    for (const char c : name) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_'))
            return false;
    }
    return true;
}

bool positiveInt(const QJsonValue &value, int *out)
{
    if (!value.isDouble())
        return false;
    const double number = value.toDouble();
    if (!(number >= 1.0 && number <= 1048576.0) || number != std::floor(number))
        return false;
    *out = int(number);
    return true;
}

void countLive(QAtomicInteger<int> &live, QAtomicInteger<qint64> &bytes, qint64 size, int sign)
{
    live.fetchAndAddRelaxed(sign);
    bytes.fetchAndAddRelaxed(sign * size);
}

QShader shaderFrom(const unsigned char *data, unsigned int size)
{
    return QShader::fromSerialized(QByteArray(reinterpret_cast<const char *>(data), int(size)));
}

} // namespace

QString storageAccessName(StorageAccess access)
{
    return QLatin1String(kAccessNames[int(access)]);
}

bool parseStorageAccess(const QString &text, StorageAccess *out)
{
    for (int i = 0; i < 3; ++i) {
        if (text == QLatin1String(kAccessNames[i])) {
            *out = StorageAccess(i);
            return true;
        }
    }
    return false;
}

QString computeResourceName(ComputeResource kind)
{
    return QLatin1String(kResourceNames[int(kind)]);
}

QString storageFormatName(QRhiTexture::Format format)
{
    for (const FormatName &f : kFormats) {
        if (f.format == format)
            return QLatin1String(f.name);
    }
    return QStringLiteral("?");
}

bool parseStorageFormat(const QString &text, QRhiTexture::Format *out)
{
    for (const FormatName &f : kFormats) {
        if (text == QLatin1String(f.name)) {
            *out = f.format;
            return true;
        }
    }
    return false;
}

int storageTexelBytes(QRhiTexture::Format format)
{
    for (const FormatName &f : kFormats) {
        if (f.format == format)
            return f.texelBytes;
    }
    return 0;
}

int storageReflectedFormat(QRhiTexture::Format format)
{
    for (const FormatName &f : kFormats) {
        if (f.format == format)
            return f.reflected;
    }
    return int(QShaderDescription::ImageFormatUnknown);
}

// ------------------------------------------------------------------------------------------- declarations

bool StorageBufferDeclaration::sameShape(const StorageBufferDeclaration &o) const
{
    if (name != o.name || vertex != o.vertex || indirect != o.indirect || layout.stride != o.layout.stride
        || layout.attributes.size() != o.layout.attributes.size())
        return false;
    for (qsizetype i = 0; i < layout.attributes.size(); ++i) {
        const MeshAttribute &a = layout.attributes.at(i);
        const MeshAttribute &b = o.layout.attributes.at(i);
        if (a.name != b.name || a.components != b.components || a.offset != b.offset)
            return false;
    }
    return true;
}

QJsonObject StorageBufferDeclaration::toJson() const
{
    QJsonObject o;
    o.insert(QStringLiteral("name"), QString::fromLatin1(name));
    o.insert(QStringLiteral("bytes"), bytes.toJson());
    QJsonArray usage;
    if (vertex)
        usage.append(QStringLiteral("vertex"));
    if (indirect)
        usage.append(QStringLiteral("indirect"));
    o.insert(QStringLiteral("usage"), usage);
    if (vertex)
        o.insert(QStringLiteral("layout"), layout.toJson());
    return o;
}

bool parseStorageBuffer(const QJsonValue &value, StorageBufferDeclaration *out, QString *error)
{
    const QJsonObject o = value.toObject();
    StorageBufferDeclaration b;
    b.name = o.value(QStringLiteral("name")).toString().toLatin1();
    const bool withUsage = o.contains(QStringLiteral("usage"));
    const bool withLayout = o.contains(QStringLiteral("layout"));
    bool ok = value.isObject() && o.size() == 2 + (withUsage ? 1 : 0) + (withLayout ? 1 : 0) && identifier(b.name)
        && parseDrawCount(o.value(QStringLiteral("bytes")), false, &b.bytes)
        && (b.bytes.kind != DrawCount::Kind::Number
            || (b.bytes.number > 0 && b.bytes.number % 4 == 0 && qint64(b.bytes.number) <= kMaxStorageBufferBytes));
    if (ok && withUsage) {
        const QJsonValue usage = o.value(QStringLiteral("usage"));
        ok = usage.isArray();
        for (const QJsonValue &u : usage.toArray()) {
            const QString text = u.toString();
            if (text == QLatin1String("vertex") && !b.vertex)
                b.vertex = true;
            else if (text == QLatin1String("indirect") && !b.indirect)
                b.indirect = true;
            else
                ok = false;
        }
    }
    if (!ok || withLayout != b.vertex) {
        *error = QStringLiteral("a storage buffer is {\"name\": an identifier, \"bytes\": a multiple of 4 up to %1 or a "
                                "setting's name, \"usage\"?: [\"vertex\", \"indirect\"], \"layout\": a record layout "
                                "(with \"vertex\" only)}").arg(kMaxStorageBufferBytes);
        return false;
    }
    if (withLayout && !parseRecordLayout(o.value(QStringLiteral("layout")), &b.layout,
                                         QStringLiteral("storage buffer '%1'").arg(QString::fromLatin1(b.name)), error))
        return false;
    *out = b;
    return true;
}

bool StorageImageDeclaration::sameShape(const StorageImageDeclaration &o) const
{
    return name == o.name && dimensions == o.dimensions && format == o.format;
}

bool StorageImageDeclaration::sameSize(const StorageImageDeclaration &o) const
{
    return size[0] == o.size[0] && size[1] == o.size[1] && size[2] == o.size[2];
}

QJsonObject StorageImageDeclaration::toJson() const
{
    QJsonObject o;
    o.insert(QStringLiteral("name"), QString::fromLatin1(name));
    o.insert(QStringLiteral("dimensions"), dimensions);
    o.insert(QStringLiteral("format"), storageFormatName(format));
    QJsonArray s { size[0], size[1] };
    if (dimensions == 3)
        s.append(size[2]);
    o.insert(QStringLiteral("size"), s);
    return o;
}

bool storageImageSizeFits(const StorageImageDeclaration &image, const int *size, QString *error)
{
    const int side = image.dimensions == 3 ? kMaxStorageImageSide3D : kMaxStorageImageSide2D;
    const int count = image.dimensions == 3 ? 3 : 2;
    for (int i = 0; i < count; ++i) {
        if (size[i] < 1 || size[i] > side) {
            *error = QStringLiteral("storage image '%1': each side is 1 to %2").arg(QString::fromLatin1(image.name))
                         .arg(side);
            return false;
        }
    }
    if (image.dimensions == 2 && size[2] != 1) {
        *error = QStringLiteral("storage image '%1' is 2D: no depth").arg(QString::fromLatin1(image.name));
        return false;
    }
    return true;
}

bool parseStorageImage(const QJsonValue &value, StorageImageDeclaration *out, QString *error)
{
    const QJsonObject o = value.toObject();
    StorageImageDeclaration image;
    image.name = o.value(QStringLiteral("name")).toString().toLatin1();
    const QJsonValue dims = o.value(QStringLiteral("dimensions"));
    image.dimensions = dims.isDouble() ? int(dims.toDouble()) : 0;
    const QJsonArray size = o.value(QStringLiteral("size")).toArray();
    bool ok = value.isObject() && o.size() == 4 && identifier(image.name)
        && (image.dimensions == 2 || image.dimensions == 3)
        && parseStorageFormat(o.value(QStringLiteral("format")).toString(), &image.format)
        && size.size() == image.dimensions;
    for (int i = 0; ok && i < image.dimensions; ++i)
        ok = positiveInt(size.at(i), &image.size[i]);
    if (ok && image.dimensions == 2)
        image.size[2] = 1;
    if (!ok) {
        *error = QStringLiteral("a storage image is {\"name\": an identifier, \"dimensions\": 2 or 3, \"format\": rgba8, "
                                "rgba16f, rgba32f, r16f or r32f, \"size\": [w, h] or [w, h, d]}");
        return false;
    }
    if (!storageImageSizeFits(image, image.size, error))
        return false;
    *out = image;
    return true;
}

QJsonObject ComputeBinding::toJson() const
{
    return QJsonObject { { QStringLiteral("name"), QString::fromLatin1(name) },
                         { computeResourceName(kind), QString::fromLatin1(resource) },
                         { QStringLiteral("access"), storageAccessName(access) },
                         { QStringLiteral("binding"), binding } };
}

QJsonValue ComputeTrigger::toJson() const
{
    if (kind == Kind::Field)
        return QJsonObject { { QStringLiteral("field"), QString::fromLatin1(field) } };
    return QStringLiteral("frame");
}

bool parseComputeTrigger(const QJsonValue &value, ComputeTrigger *out)
{
    ComputeTrigger t;
    if (value.isString() && value.toString() == QLatin1String("frame")) {
        *out = t;
        return true;
    }
    const QJsonObject o = value.toObject();
    t.field = o.value(QStringLiteral("field")).toString().toLatin1();
    if (!value.isObject() || o.size() != 1 || !identifier(t.field))
        return false;
    t.kind = ComputeTrigger::Kind::Field;
    *out = t;
    return true;
}

// ------------------------------------------------------------------------------------------- counts and controls

ComputeCounts computeCounts()
{
    ComputeCounts c;
    c.buffers = g_buffers.loadRelaxed();
    c.bufferBytes = g_bufferBytes.loadRelaxed();
    c.images = g_images.loadRelaxed();
    c.imageBytes = g_imageBytes.loadRelaxed();
    c.dispatches = g_dispatches.loadRelaxed();
    c.computePasses = g_computePasses.loadRelaxed();
    c.skipped = g_skipped.loadRelaxed();
    c.clears = g_clears.loadRelaxed();
    c.copies = g_copies.loadRelaxed();
    c.imageZeroUploads = g_imageZeroUploads.loadRelaxed();
    c.objectsCreated = g_objectsCreated.loadRelaxed();
    c.readbacksPending = g_readbacksPending.loadRelaxed();
    c.statesLost = g_statesLost.loadRelaxed();
    return c;
}

void countDispatch() { g_dispatches.fetchAndAddRelaxed(1); }
void countComputePass() { g_computePasses.fetchAndAddRelaxed(1); }
void countSkipped() { g_skipped.fetchAndAddRelaxed(1); }
void countStateLost() { g_statesLost.fetchAndAddRelaxed(1); }

void setComputeWriteAsRead(bool on) { g_writeAsRead.storeRelaxed(on ? 1 : 0); }
bool computeWriteAsRead() { return g_writeAsRead.loadRelaxed() != 0; }
void setComputeSinglePass(bool on) { g_singlePass.storeRelaxed(on ? 1 : 0); }
bool computeSinglePass() { return g_singlePass.loadRelaxed() != 0; }
void setComputeTriggerEveryRecord(bool on) { g_triggerEveryRecord.storeRelaxed(on ? 1 : 0); }
bool computeTriggerEveryRecord() { return g_triggerEveryRecord.loadRelaxed() != 0; }
void setSkipStorageRelease(bool on) { g_skipStorageRelease.storeRelaxed(on ? 1 : 0); }
bool skipStorageRelease() { return g_skipStorageRelease.loadRelaxed() != 0; }

QJsonObject computeDeviceFacts(QRhi *rhi)
{
    QJsonObject o;
    if (!rhi)
        return o;
    o.insert(QStringLiteral("compute"), rhi->isFeatureSupported(QRhi::Compute));
    o.insert(QStringLiteral("three_dimensional_textures"), rhi->isFeatureSupported(QRhi::ThreeDimensionalTextures));
    o.insert(QStringLiteral("max_thread_groups_per_dimension"),
             rhi->resourceLimit(QRhi::MaxThreadGroupsPerDimension));
    o.insert(QStringLiteral("max_threads_per_thread_group"), rhi->resourceLimit(QRhi::MaxThreadsPerThreadGroup));
    o.insert(QStringLiteral("max_thread_group_x"), rhi->resourceLimit(QRhi::MaxThreadGroupX));
    o.insert(QStringLiteral("max_thread_group_y"), rhi->resourceLimit(QRhi::MaxThreadGroupY));
    o.insert(QStringLiteral("max_thread_group_z"), rhi->resourceLimit(QRhi::MaxThreadGroupZ));
    QJsonObject formats;
    for (const FormatName &f : kFormats)
        formats.insert(QLatin1String(f.name), rhi->isTextureFormatSupported(f.format, QRhiTexture::UsedWithLoadStore));
    o.insert(QStringLiteral("load_store_formats"), formats);
    return o;
}

// ------------------------------------------------------------------------------------------- harness readback

QList<StoragePixels> StorageReadback::take() const
{
    QList<StoragePixels> out;
    for (qsizetype i = 0; i < items.size(); ++i) {
        StoragePixels p = items.at(i);
        for (int r = 0; r < resultCount.at(i); ++r)
            p.data.append(results[firstResult.at(i) + r].data);
        out.append(p);
    }
    return out;
}

std::shared_ptr<StorageReadback> ModeStorage::startReadback(QRhiResourceUpdateBatch *updates) const
{
    auto set = std::make_shared<StorageReadback>();
    int total = 0;
    for (const Buffer *b : m_buffers)
        total += b->buffer ? 1 : 0;
    for (const Image *i : m_images)
        total += i->texture ? i->decl.size[2] : 0;
    set->count = total;
    if (total == 0)
        return set;
    set->results.reset(new QRhiReadbackResult[size_t(total)]);
    set->pending.storeRelease(total);
    g_readbacksPending.fetchAndAddRelaxed(1);
    StorageReadback *raw = set.get();
    const auto completed = [raw]() {
        if (raw->pending.fetchAndAddOrdered(-1) == 1)
            g_readbacksPending.fetchAndAddRelaxed(-1);
    };
    int r = 0;
    for (const Buffer *b : m_buffers) {
        if (!b->buffer)
            continue;
        StoragePixels p;
        p.name = QString::fromLatin1(b->decl.name);
        p.kind = QStringLiteral("buffer");
        p.format = QStringLiteral("bytes");
        p.size[0] = int(b->bytes);
        set->items.append(p);
        set->firstResult.append(r);
        set->resultCount.append(1);
        set->results[r].completed = completed;
        updates->readBackBuffer(b->buffer.get(), 0, b->bytes, &set->results[r]);
        ++r;
    }
    for (const Image *i : m_images) {
        if (!i->texture)
            continue;
        StoragePixels p;
        p.name = QString::fromLatin1(i->decl.name);
        p.kind = QStringLiteral("image");
        p.format = storageFormatName(i->decl.format);
        for (int k = 0; k < 3; ++k)
            p.size[k] = i->decl.size[k];
        set->items.append(p);
        set->firstResult.append(r);
        set->resultCount.append(i->decl.size[2]);
        for (int slice = 0; slice < i->decl.size[2]; ++slice) {
            QRhiReadbackDescription rb(i->texture.get());
            rb.setLayer(slice);              // a 3D image's slice (the harness box settles QRhi's reading of it)
            set->results[r].completed = completed;
            updates->readBackTexture(rb, &set->results[r]);
            ++r;
        }
    }
    return set;
}

// ------------------------------------------------------------------------------------------- ModeStorage

ModeStorage::~ModeStorage()
{
    release();
}

const ModeStorage::Buffer *ModeStorage::buffer(const QByteArray &name) const
{
    for (const Buffer *b : m_buffers) {
        if (b->decl.name == name && b->buffer)
            return b;
    }
    return nullptr;
}

const ModeStorage::Image *ModeStorage::image(const QByteArray &name) const
{
    for (const Image *i : m_images) {
        if (i->decl.name == name && i->texture)
            return i;
    }
    return nullptr;
}

int ModeStorage::live() const
{
    int n = 0;
    for (const Buffer *b : m_buffers)
        n += b->buffer ? 1 : 0;
    for (const Image *i : m_images)
        n += i->texture ? 1 : 0;
    n += m_clear ? 1 : 0;
    n += m_copy ? 1 : 0;
    n += m_opBlocks ? 1 : 0;
    n += m_dummy ? 1 : 0;
    return n;
}

void ModeStorage::releaseBuffer(Buffer *b)
{
    if (b->buffer)
        countLive(g_buffers, g_bufferBytes, qint64(b->bytes), -1);
    b->buffer.reset();                        // QRhi releases the native buffer after the frames that use it
    delete b;
    ++m_objects;
}

void ModeStorage::releaseImage(Image *i)
{
    if (i->texture)
        countLive(g_images, g_imageBytes, i->bytes, -1);
    i->texture.reset();
    delete i;
    ++m_objects;
}

void ModeStorage::releaseKernels()
{
    for (auto &bindings : m_opBindings)
        bindings.reset();
    m_clear.reset();
    m_copy.reset();
    m_clearLayout.reset();
    m_copyLayout.reset();
    m_opBlocks.reset();
    m_dummy.reset();
    m_kernelRhi = nullptr;
}

void ModeStorage::release()
{
    if (skipStorageRelease())
        return;                               // the retirement proof's control: the storage left behind (counted)
    m_opCount = 0;
    releaseKernels();
    for (Buffer *b : m_retiring)
        releaseBuffer(b);
    m_retiring.clear();
    for (Buffer *b : m_buffers)
        releaseBuffer(b);
    m_buffers.clear();
    for (Image *i : m_images)
        releaseImage(i);
    m_images.clear();
    m_zeros.clear();
}

bool ModeStorage::sync(QRhi *rhi, QRhiResourceUpdateBatch *updates, const QList<StorageBufferDeclaration> &buffers,
                       const QList<StorageImageDeclaration> &images, const QHash<QByteArray, double> &settings,
                       bool *fresh, QString *error)
{
    *fresh = false;
    m_uploaded = false;
    // Phase 1: every size checked and every new object made; a failure changes nothing (the storage stays drawn).
    struct Made
    {
        qsizetype index = -1;                 // the declaration's
        Buffer *existing = nullptr;
        std::unique_ptr<QRhiBuffer> buffer;
        quint32 bytes = 0;
    };
    struct MadeImage
    {
        qsizetype index = -1;
        std::unique_ptr<QRhiTexture> texture;
    };
    QList<quint32> sizes;
    for (const StorageBufferDeclaration &decl : buffers) {
        double bytes = decl.bytes.number;
        if (decl.bytes.kind == DrawCount::Kind::Named) {
            if (!settings.contains(decl.bytes.name)) {
                *error = QStringLiteral("storage buffer '%1': no setting '%2' sizes it")
                             .arg(QString::fromLatin1(decl.name), QString::fromLatin1(decl.bytes.name));
                return false;
            }
            bytes = settings.value(decl.bytes.name);
        }
        if (!(bytes >= 4.0 && bytes <= double(kMaxStorageBufferBytes)) || bytes != std::floor(bytes)
            || qint64(bytes) % 4 != 0) {
            *error = QStringLiteral("storage buffer '%1': %2 bytes is not a multiple of 4 from 4 to %3")
                         .arg(QString::fromLatin1(decl.name)).arg(bytes).arg(kMaxStorageBufferBytes);
            return false;
        }
        sizes.append(quint32(bytes));
    }
    for (const StorageImageDeclaration &decl : images) {
        if (!rhi->isTextureFormatSupported(decl.format, QRhiTexture::UsedWithLoadStore)
            || (decl.dimensions == 3 && !rhi->isFeatureSupported(QRhi::ThreeDimensionalTextures))) {
            *error = QStringLiteral("storage image '%1': this device cannot load and store %2 %3D images")
                         .arg(QString::fromLatin1(decl.name), storageFormatName(decl.format)).arg(decl.dimensions);
            return false;
        }
    }
    QList<Made *> made;                       // owned until phase 2 (Qt containers only)
    QList<MadeImage *> madeImages;
    const auto drop = [&made, &madeImages]() {
        for (Made *m : made)
            delete m;
        for (MadeImage *m : madeImages)
            delete m;
        made.clear();
        madeImages.clear();
    };
    for (qsizetype k = 0; k < buffers.size(); ++k) {
        const StorageBufferDeclaration &decl = buffers.at(k);
        Buffer *existing = nullptr;
        for (Buffer *b : m_buffers) {
            if (b->decl.name == decl.name)
                existing = b;
        }
        if (existing && existing->buffer && existing->decl.sameShape(decl) && existing->bytes == sizes.at(k))
            continue;                         // kept
        QRhiBuffer::UsageFlags usage = QRhiBuffer::StorageBuffer;
        if (decl.vertex)
            usage |= QRhiBuffer::VertexBuffer;
        if (decl.indirect)
            usage |= QRhiBuffer::IndirectBuffer;
        Made *m = new Made;
        m->index = k;
        m->existing = existing;
        m->bytes = sizes.at(k);
        m->buffer.reset(rhi->newBuffer(QRhiBuffer::Static, usage, m->bytes));
        m->buffer->setName(QByteArrayLiteral("srpss core storage buffer ") + decl.name);
        made.append(m);
        g_objectsCreated.fetchAndAddRelaxed(1);
        if (!m->buffer->create()) {
            *error = QStringLiteral("storage buffer '%1' (%2 bytes) could not be created")
                         .arg(QString::fromLatin1(decl.name)).arg(m->bytes);
            drop();
            return false;
        }
    }
    if (!made.isEmpty() && !ensureKernels(rhi, error)) {
        drop();
        return false;
    }
    for (qsizetype k = 0; k < images.size(); ++k) {
        const StorageImageDeclaration &decl = images.at(k);
        Image *existing = nullptr;
        for (Image *i : m_images) {
            if (i->decl.name == decl.name)
                existing = i;
        }
        if (existing && existing->texture && existing->decl.sameShape(decl) && existing->decl.sameSize(decl))
            continue;                         // kept
        const QRhiTexture::Flags flags = QRhiTexture::UsedWithLoadStore
            | (decl.dimensions == 3 ? QRhiTexture::ThreeDimensional : QRhiTexture::Flags());
        MadeImage *m = new MadeImage;
        m->index = k;
        m->texture.reset(decl.dimensions == 3
            ? rhi->newTexture(decl.format, decl.size[0], decl.size[1], decl.size[2], 1, flags)
            : rhi->newTexture(decl.format, QSize(decl.size[0], decl.size[1]), 1, flags));
        m->texture->setName(QByteArrayLiteral("srpss core storage image ") + decl.name);
        madeImages.append(m);
        g_objectsCreated.fetchAndAddRelaxed(1);
        if (!m->texture->create()) {
            *error = QStringLiteral("storage image '%1' could not be created").arg(QString::fromLatin1(decl.name));
            drop();
            return false;
        }
    }
    // Phase 2: commit. A new buffer is zeroed by the clear kernel; one that replaces a buffer of the same shape (its size
    // changed) takes its prefix through the copy kernel (D16 choice C: the drift's history survives a capacity change);
    // the replaced one goes after the edge's copy is recorded.
    const auto edgeOp = [this](const Op &op) {
        if (m_opCount < kMaxStorageEdgeOps)
            m_ops[m_opCount++] = op;
    };
    QList<Buffer *> next;
    for (qsizetype k = 0; k < buffers.size(); ++k) {
        const StorageBufferDeclaration &decl = buffers.at(k);
        Made *m = nullptr;
        for (Made *candidate : made) {
            if (candidate->index == k)
                m = candidate;
        }
        if (!m) {
            for (Buffer *b : m_buffers) {
                if (b->decl.name == decl.name) {
                    b->decl = decl;           // kept (its size and shape hold)
                    next.append(b);
                }
            }
            continue;
        }
        Buffer *b = new Buffer;
        b->decl = decl;
        b->bytes = m->bytes;
        b->buffer = std::move(m->buffer);
        countLive(g_buffers, g_bufferBytes, qint64(b->bytes), 1);
        edgeOp(Op { false, b->buffer.get(), nullptr, 0u, 0u, b->bytes / 4u });
        if (m->existing && m->existing->buffer && m->existing->decl.sameShape(decl)) {
            edgeOp(Op { true, b->buffer.get(), m->existing->buffer.get(), 0u, 0u,
                        qMin(b->bytes, m->existing->bytes) / 4u });
        } else {
            *fresh = true;
        }
        next.append(b);
        ++m_objects;
    }
    for (Buffer *b : m_buffers) {
        if (!next.contains(b))
            m_retiring.append(b);             // replaced or no longer declared: released after the edge
    }
    m_buffers = next;
    QList<Image *> nextImages;
    for (qsizetype k = 0; k < images.size(); ++k) {
        const StorageImageDeclaration &decl = images.at(k);
        MadeImage *m = nullptr;
        for (MadeImage *candidate : madeImages) {
            if (candidate->index == k)
                m = candidate;
        }
        if (!m) {
            for (Image *i : m_images) {
                if (i->decl.name == decl.name)
                    nextImages.append(i);
            }
            continue;
        }
        // Zeroed by one upload at this edge: a slice of zeros, shared by every slice (an image's content is its
        // dispatches' work: no prefix is kept).
        const qsizetype slice = qsizetype(decl.size[0]) * decl.size[1] * storageTexelBytes(decl.format);
        const QByteArray zeros(slice, '\0');
        QList<QRhiTextureUploadEntry> entries;
        for (int s = 0; s < decl.size[2]; ++s)
            entries.append(QRhiTextureUploadEntry(s, 0, QRhiTextureSubresourceUploadDescription(zeros)));
        QRhiTextureUploadDescription description;
        description.setEntries(entries.cbegin(), entries.cend());
        updates->uploadTexture(m->texture.get(), description);
        m_uploaded = true;
        g_imageZeroUploads.fetchAndAddRelaxed(1);
        Image *i = new Image;
        i->decl = decl;
        i->texture = std::move(m->texture);
        i->bytes = qint64(slice) * decl.size[2];
        countLive(g_images, g_imageBytes, i->bytes, 1);
        nextImages.append(i);
        *fresh = true;
        ++m_objects;
    }
    for (Image *i : m_images) {
        if (!nextImages.contains(i))
            releaseImage(i);                  // its bindings are made again before any pass reads the new one
    }
    m_images = nextImages;
    drop();
    if (m_buffers.isEmpty() && m_images.isEmpty() && m_opCount == 0 && m_retiring.isEmpty())
        releaseKernels();
    return true;
}

bool ModeStorage::ensureKernels(QRhi *rhi, QString *error)
{
    if (m_kernelRhi == rhi && m_clear && m_copy)
        return true;
    releaseKernels();
    const QShader clear = shaderFrom(storage_clear_comp_qsb, storage_clear_comp_qsb_size);
    const QShader copy = shaderFrom(storage_copy_comp_qsb, storage_copy_comp_qsb_size);
    if (!clear.isValid() || !copy.isValid() || !rhi->isFeatureSupported(QRhi::Compute)) {
        *error = QStringLiteral("the storage kernels need QRhi::Compute and their shaders (storage_clear.comp, "
                                "storage_copy.comp)");
        return false;
    }
    m_opStride = quint32(rhi->ubufAligned(int(kKernelBlockBytes)));
    m_opBlocks.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer, m_opStride * kMaxStorageEdgeOps));
    m_opBlocks->setName(QByteArrayLiteral("srpss core storage kernel blocks"));
    m_dummy.reset(rhi->newBuffer(QRhiBuffer::Static, QRhiBuffer::StorageBuffer, 16));
    m_dummy->setName(QByteArrayLiteral("srpss core storage kernel layout buffer"));
    g_objectsCreated.fetchAndAddRelaxed(2);
    bool ok = m_opBlocks->create() && m_dummy->create();
    const QRhiShaderResourceBinding::StageFlags cs = QRhiShaderResourceBinding::ComputeStage;
    m_clearLayout.reset(rhi->newShaderResourceBindings());
    m_clearLayout->setBindings({ QRhiShaderResourceBinding::uniformBufferWithDynamicOffset(0, cs, m_opBlocks.get(),
                                                                                           kKernelBlockBytes),
                                 QRhiShaderResourceBinding::bufferStore(1, cs, m_dummy.get()) });
    m_copyLayout.reset(rhi->newShaderResourceBindings());
    m_copyLayout->setBindings({ QRhiShaderResourceBinding::uniformBufferWithDynamicOffset(0, cs, m_opBlocks.get(),
                                                                                          kKernelBlockBytes),
                                QRhiShaderResourceBinding::bufferStore(1, cs, m_dummy.get()),
                                QRhiShaderResourceBinding::bufferLoad(2, cs, m_dummy.get()) });
    g_objectsCreated.fetchAndAddRelaxed(2);
    ok = ok && m_clearLayout->create() && m_copyLayout->create();
    m_clear.reset(rhi->newComputePipeline());
    m_clear->setName(QByteArrayLiteral("srpss core storage clear"));
    m_clear->setShaderStage({ QRhiShaderStage::Compute, clear });
    m_clear->setShaderResourceBindings(m_clearLayout.get());
    m_copy.reset(rhi->newComputePipeline());
    m_copy->setName(QByteArrayLiteral("srpss core storage copy"));
    m_copy->setShaderStage({ QRhiShaderStage::Compute, copy });
    m_copy->setShaderResourceBindings(m_copyLayout.get());
    g_objectsCreated.fetchAndAddRelaxed(2);
    ok = ok && m_clear->create() && m_copy->create();
    if (!ok) {
        releaseKernels();
        *error = QStringLiteral("the storage kernels could not be created");
        return false;
    }
    m_kernelRhi = rhi;
    return true;
}

QRhiResourceUpdateBatch *ModeStorage::recordEdges(QRhi *rhi, QRhiCommandBuffer *cb, QRhiResourceUpdateBatch *updates)
{
    if (m_opCount == 0) {
        for (Buffer *b : m_retiring)
            releaseBuffer(b);
        m_retiring.clear();
        return updates;
    }
    // Each operation's block at its offset, written whole once (the fast path; never a batch update): its range and the
    // dispatch's invocations, the stride each invocation steps by.
    const QRhiShaderResourceBinding::StageFlags cs = QRhiShaderResourceBinding::ComputeStage;
    const quint32 maxGroups = quint32(qMax(1, qMin(rhi->resourceLimit(QRhi::MaxThreadGroupsPerDimension), 65535)));
    const auto groupsOf = [maxGroups](quint32 words) {
        return qMin((words + kStorageKernelGroup - 1) / kStorageKernelGroup, maxGroups);
    };
    char *p = m_opBlocks ? m_opBlocks->beginFullDynamicBufferUpdateForCurrentFrame() : nullptr;
    if (p) {
        for (int k = 0; k < m_opCount; ++k) {
            const Op &op = m_ops[k];
            const quint32 block[8] = { op.dstWord, op.srcWord, op.words, 0u, groupsOf(op.words) * kStorageKernelGroup,
                                       0u, 0u, 0u };
            std::memcpy(p + quint64(k) * m_opStride, block, sizeof(block));
        }
    }
    if (m_opBlocks)
        m_opBlocks->endFullDynamicBufferUpdateForCurrentFrame();
    QRhiResourceUpdateBatch *pending = updates;
    for (int k = 0; k < m_opCount; ++k) {
        const Op &op = m_ops[k];
        if (!op.dst || op.words == 0 || (op.copy && !op.src))
            continue;
        std::unique_ptr<QRhiShaderResourceBindings> &bindings = m_opBindings[k];
        bindings.reset(rhi->newShaderResourceBindings());
        const QRhiShaderResourceBinding block = QRhiShaderResourceBinding::uniformBufferWithDynamicOffset(
            0, cs, m_opBlocks.get(), kKernelBlockBytes);
        if (op.copy) {
            bindings->setBindings({ block, QRhiShaderResourceBinding::bufferStore(1, cs, op.dst),
                                    QRhiShaderResourceBinding::bufferLoad(2, cs, op.src) });
        } else {
            bindings->setBindings({ block, QRhiShaderResourceBinding::bufferStore(1, cs, op.dst) });
        }
        g_objectsCreated.fetchAndAddRelaxed(1);
        if (!bindings->create())
            continue;
        // One QRhi compute pass an operation (D16 choice A): the clear before the copy into the same buffer is a
        // write-after-write QRhi barriers at the boundary.
        cb->beginComputePass(pending);
        pending = nullptr;
        cb->setComputePipeline(op.copy ? m_copy.get() : m_clear.get());
        const QRhiCommandBuffer::DynamicOffset offset { 0, quint32(k) * m_opStride };
        cb->setShaderResources(bindings.get(), 1, &offset);
        cb->dispatch(int(groupsOf(op.words)), 1, 1);
        cb->endComputePass();
        countComputePass();
        (op.copy ? g_copies : g_clears).fetchAndAddRelaxed(1);
    }
    m_opCount = 0;
    // The replaced buffers go now: their copies are recorded (QRhi releases the native objects after the frame).
    for (Buffer *b : m_retiring)
        releaseBuffer(b);
    m_retiring.clear();
    return pending;
}

QJsonObject ModeStorage::stateJson() const
{
    QJsonArray buffers;
    for (const Buffer *b : m_buffers) {
        QJsonObject o = b->decl.toJson();
        o.insert(QStringLiteral("allocated_bytes"), double(b->bytes));
        buffers.append(o);
    }
    QJsonArray images;
    for (const Image *i : m_images) {
        QJsonObject o = i->decl.toJson();
        o.insert(QStringLiteral("allocated_bytes"), double(i->bytes));
        images.append(o);
    }
    QJsonObject o;
    o.insert(QStringLiteral("buffers"), buffers);
    o.insert(QStringLiteral("images"), images);
    o.insert(QStringLiteral("objects"), double(m_objects));
    o.insert(QStringLiteral("kernels"), bool(m_clear));
    return o;
}

